{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.inwards_planned_mom as with meta_map as ( select UPPER( IFF( UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(SKU_GROUP, \' \', \'\')) LIKE \'4C-%\', REGEXP_REPLACE( REPLACE(SKU_GROUP, \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\' ), REGEXP_REPLACE(REPLACE(SKU_GROUP, \' \', \'\'), \'-.*$\', \'\') ) ) AS sku_group_clean, COALESCE( MIN( CASE WHEN UPPER(TRIM(a.l1_category)) = \'LONG TAIL\' THEN a.l1_category END ), MIN( CASE WHEN UPPER(TRIM(a.l1_category)) = \'PLUS\' THEN a.l1_category END ), MIN( CASE WHEN UPPER(TRIM(a.l1_category)) = \'LUXE\' THEN a.l1_category END ), MIN( CASE WHEN UPPER(TRIM(a.l1_category)) = \'SNITCH\' THEN a.l1_category END ), MIN(a.l1_category) ) AS l1_category, COALESCE( MIN( CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.category END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.category END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.category END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.category END ), MIN(a.category) ) AS category, COALESCE( MIN( CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta1 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta1 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta1 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta1 END ), MIN(a.meta1) ) AS meta1, COALESCE( MIN( CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta2 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta2 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta2 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta2 END ), MIN(a.meta2) ) AS meta2, COALESCE( MIN( CASE WHEN UPPER(TRIM(a.category)) = \'SHIRTS\' THEN a.meta3 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TSHIRTS\' THEN a.meta3 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'JEANS\' THEN a.meta3 END ), MIN( CASE WHEN UPPER(TRIM(a.category)) = \'TROUSERS\' THEN a.meta3 END ), MIN(a.meta3) ) AS meta3, avg(cogs) cogs from snitch_db.maplemonk.meta_mapping_cogs_sku a group by 1 ), month_map AS ( SELECT \'APRIL\' AS month_text, TO_DATE(\'2026-04-01\') AS month_start UNION ALL SELECT \'MAY\' , TO_DATE(\'2026-05-01\') UNION ALL SELECT \'JUNE\' , TO_DATE(\'2026-06-01\') UNION ALL SELECT \'JULY\' , TO_DATE(\'2026-07-01\') UNION ALL SELECT \'AUGUST\' , TO_DATE(\'2026-08-01\') UNION ALL SELECT \'SEPTEMBER\' , TO_DATE(\'2026-09-01\') UNION ALL SELECT \'OCTOBER\' , TO_DATE(\'2026-10-01\') UNION ALL SELECT \'NOVEMBER\' , TO_DATE(\'2026-11-01\') UNION ALL SELECT \'DECEMBER\' , TO_DATE(\'2026-12-01\') UNION ALL SELECT \'JANUARY\' , TO_DATE(\'2027-01-01\') UNION ALL SELECT \'FEBRUARY\' , TO_DATE(\'2027-02-01\') ), base AS ( SELECT m.month_start, t.sku, l1_category,category,meta1,meta2,meta3, TRY_TO_NUMBER(t.qty) AS planned_inwards_qty FROM snitch_db.maplemonk.inwards_list_mom_v2_sku_list_with_month_remarks t JOIN month_map m ON UPPER(t.remarks_final) LIKE \'%\' || m.month_text || \'%\' left join meta_map mm on sku_group_clean =UPPER( IFF( UPPER(REPLACE(t.sku, \' \', \'\')) LIKE \'MP%\' OR UPPER(REPLACE(t.sku, \' \', \'\')) LIKE \'4C-%\', REGEXP_REPLACE( REPLACE(t.sku, \' \', \'\'), \'^([^-]+-[^-]+).*$\', \'\\1\' ), REGEXP_REPLACE(REPLACE(t.sku, \' \', \'\'), \'-.*$\', \'\') ) ) ) SELECT l1_category,category,meta1,meta2,meta3, month_start, SUM(planned_inwards_qty) AS planned_inwards_qty FROM base where month_start>=\'2026-04-01\' GROUP BY 1,2,3,4,5,6 ;",
                    "transaction": true
                }
            ) }}
